<script setup lang="ts">const route=useRoute(),{api,token}=useShopApi();const isProduct=computed(()=>/^\/products\/[^/]+$/.test(route.path));const product=ref<any>(),reviews=ref<any>(),body=ref(''),rating=ref(5),message=ref('');async function load(){if(!isProduct.value)return;product.value=await api<any>(`/catalog/products/${route.params.slug}`);reviews.value=await api<any>(`/catalog/products/${product.value.id}/comments`)}watch(()=>route.fullPath,load,{immediate:true});async function submit(){if(!token.value)return navigateTo('/login?redirect='+encodeURIComponent(route.fullPath));const r=await api<any>(`/comments/product/${product.value.id}`,{method:'POST',body:{body:body.value,rating:rating.value}});message.value=r.message;body.value=''}async function helpful(c:any){if(!token.value)return navigateTo('/login');const r=await api<any>(`/comments/${c.id}/helpful`,{method:'POST'});c.votes_count=r.votes_count;c.helpful=r.helpful}</script>
<template><section v-if="isProduct&&product" class="mx-auto mt-6 max-w-7xl px-4"><div class="rounded-3xl border bg-white p-6 md:p-10"><div class="flex items-center justify-between"><h2 class="text-xl font-black">نظر خریداران</h2><span class="text-sm text-slate-400">{{reviews?.comments?.total||0}} دیدگاه</span></div><div class="mt-6 grid gap-6 md:grid-cols-[220px_1fr]"><div class="rounded-2xl bg-slate-50 p-5 text-center"><p class="text-4xl font-black">{{reviews?.summary?.average||0}}</p><p class="mt-1 text-amber-500">★★★★★</p><p class="mt-2 text-xs text-slate-400">از {{reviews?.summary?.ratings_count||0}} امتیاز</p><div class="mt-5 space-y-2"><div v-for="n in [5,4,3,2,1]" :key="n" class="grid grid-cols-[25px_1fr_25px] items-center gap-2 text-xs"><span>{{n}}★</span><div class="h-1.5 overflow-hidden rounded-full bg-slate-200"><div class="h-full bg-amber-400" :style="{width:`${(reviews?.summary?.distribution?.[n]||0)/Math.max(reviews?.summary?.ratings_count||1,1)*100}%`}"/></div><span>{{reviews?.summary?.distribution?.[n]||0}}</span></div></div></div><form class="rounded-2xl bg-slate-50 p-4" @submit.prevent="submit"><div class="mb-3 flex items-center gap-3"><span class="text-sm font-bold">امتیاز شما</span><div class="flex flex-row-reverse justify-end"><button v-for="n in 5" :key="n" type="button" :class="['text-2xl',n<=rating?'text-amber-400':'text-slate-300']" @click="rating=n">★</button></div></div><textarea v-model="body" required minlength="3" rows="3" class="w-full rounded-xl border p-3" placeholder="تجربه استفاده از این محصول را بنویسید…"/><p v-if="message" class="mt-2 text-sm text-emerald-700">{{message}}</p><button class="mt-3 rounded-xl bg-brand-700 px-5 py-2.5 text-sm font-bold text-white">ثبت نظر</button></form></div><div class="mt-7 space-y-4"><article v-for="c in reviews?.comments?.data" :key="c.id" class="rounded-2xl border p-5"><div class="flex justify-between"><div><p class="font-bold">{{c.user?.name||'کاربر'}}</p><p class="mt-1 text-xs text-slate-400">{{new Date(c.created_at).toLocaleDateString('fa-IR')}}</p></div><div class="flex gap-2"><span v-if="c.is_buyer" class="rounded-lg bg-emerald-50 px-2 py-1 text-xs font-bold text-emerald-700">خریدار تأییدشده</span><span class="text-sm text-amber-500">★ {{c.rating}}</span></div></div><p class="mt-3 text-sm leading-7 text-slate-600">{{c.body}}</p><div v-for="reply in c.replies" :key="reply.id" class="mt-4 rounded-xl bg-brand-50 p-4 text-sm"><b class="text-brand-800">پاسخ فروشگاه</b><p class="mt-2 leading-7 text-slate-600">{{reply.body}}</p></div><button class="mt-4 text-xs font-bold text-slate-500" @click="helpful(c)">این نظر مفید بود؟ {{c.votes_count||0}} 👍</button></article><p v-if="!reviews?.comments?.data?.length" class="py-8 text-center text-sm text-slate-400">هنوز نظری منتشر نشده؛ اولین نفر باشید.</p></div></div></section></template>
